import {
  Box,
  Typography,
  TextField,
  InputAdornment,
  IconButton,
  Button,
} from '@mui/material';
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';
import PersonOutlineIcon from '@mui/icons-material/PersonOutline';
import MailOutlineIcon from '@mui/icons-material/MailOutline';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import { useFormik } from 'formik';
import { toast } from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';
import { useState } from 'react';
import { useDispatch } from 'react-redux';
import { useTheme } from '@mui/material/styles';
import useMediaQuery from '@mui/material/useMediaQuery';
import BaseCard from '../../../components/Cards/Card';
import PasswordStrengthBar from '../../../components/PasswordStrengthBar';
import { setSignupData } from '../../../Redux/Slices/AuthSlice';
import { checkEmail } from '../../../utils/userApi';

const Signup = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [checkingEmail, setCheckingEmail] = useState(false);
  const [emailTakenError, setEmailTakenError] = useState('');

  const validate = (values) => {
    const errors = {};

    const fullName = values.fullName.trim();
    if (!fullName) {
      errors.fullName = 'Full name is required';
    } else if (fullName.length < 3) {
      errors.fullName = 'Full name must be at least 3 characters';
    } else if (fullName.length > 50) {
      errors.fullName = 'Full name must be at most 50 characters';
    } else if (!/^[a-zA-Z][a-zA-Z\s'-]*$/.test(fullName)) {
      errors.fullName = 'Full name can only contain letters, spaces, hyphens and apostrophes';
    }

    const email = values.email.trim();
    if (!email) {
      errors.email = 'Email is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      errors.email = 'Email is invalid';
    }

    if (!values.password) {
      errors.password = 'Password is required';
    } else if (values.password.length < 8) {
      errors.password = 'Password must be at least 8 characters';
    } else if (!/[A-Z]/.test(values.password)) {
      errors.password = 'Password must contain at least one uppercase letter';
    } else if (!/[a-z]/.test(values.password)) {
      errors.password = 'Password must contain at least one lowercase letter';
    } else if (!/[0-9]/.test(values.password)) {
      errors.password = 'Password must contain at least one number';
    } else if (!/[^A-Za-z0-9]/.test(values.password)) {
      errors.password = 'Password must contain at least one special character';
    }

    if (!values.confirmPassword) {
      errors.confirmPassword = 'Please confirm your password';
    } else if (values.confirmPassword !== values.password) {
      errors.confirmPassword = 'Passwords do not match';
    }

    return errors;
  };

  const formik = useFormik({
    initialValues: {
      fullName: '',
      email: '',
      password: '',
      confirmPassword: '',
    },
    validate,
    onSubmit: async (values) => {
      const email = values.email.trim().toLowerCase();

      setCheckingEmail(true);
      setEmailTakenError('');
      try {
        const result = await checkEmail(email);
        if (result?.exists || result?.available === false) {
          setEmailTakenError('This email is already in use');
          return;
        }
      } catch (error) {
        toast.error(error.message || 'Unable to verify email. Please try again.');
        return;
      } finally {
        setCheckingEmail(false);
      }

      const payload = {
        fullName: values.fullName.trim(),
        email,
        password: values.password,
      };

      dispatch(setSignupData(payload));
      toast.success('Account created. Choose your plan.');

      navigate('/app-plans', { replace: true });
    },
  });

  const showError = (field) =>
    (formik.touched[field] || formik.submitCount > 0) &&
    Boolean(formik.errors[field]);

  const errorText = (field) =>
    formik.touched[field] || formik.submitCount > 0
      ? formik.errors[field]
      : '';

  return (
    <Box sx={{ width: '100%', display: 'flex', justifyContent: 'center' }}>
      <BaseCard
        maxWidth={isMobile ? '100%' : 460}
        sx={{
          width: isMobile ? '100%' : 460,
          p: { xs: 2.5, sm: 4 },
          mt: 0,
          backgroundColor: 'rgba(0, 0, 0, 0.7)',
          backdropFilter: 'blur(16px)',
          border: '1px solid #4CC66E',
          borderRadius: '16px',
          boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.8)',
        }}
      >
        <form onSubmit={formik.handleSubmit} noValidate>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2.5 }}>
            <Box
              sx={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                gap: 1,
                mb: 0.5,
              }}
            >
              <img
                src="/favicon.svg"
                style={{ width: 84, height: 84, objectFit: 'contain' }}
                alt="Logo"
              />
            </Box>

            <Box sx={{ textAlign: 'center' }}>
              <Typography variant="h5" sx={{ color: 'white', mb: 0.5 }}>
                Create Your Account
              </Typography>
              <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                Sign up to get started
              </Typography>
            </Box>

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              <Typography variant="body2" sx={{ color: 'white' }}>
                Full Name <Box component="span" sx={{ color: '#ff6b6b' }}>*</Box>
              </Typography>
              <TextField
                fullWidth
                name="fullName"
                placeholder="John Doe"
                value={formik.values.fullName}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={showError('fullName')}
                helperText={errorText('fullName')}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <PersonOutlineIcon fontSize="small" />
                    </InputAdornment>
                  ),
                }}
              />
            </Box>

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              <Typography variant="body2" sx={{ color: 'white' }}>
                Email <Box component="span" sx={{ color: '#ff6b6b' }}>*</Box>
              </Typography>
              <TextField
                fullWidth
                name="email"
                placeholder="john@gmail.com"
                value={formik.values.email}
                onChange={(e) => {
                  if (emailTakenError) setEmailTakenError('');
                  formik.handleChange(e);
                }}
                onBlur={formik.handleBlur}
                error={Boolean(emailTakenError) || showError('email')}
                helperText={emailTakenError || errorText('email')}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <MailOutlineIcon fontSize="small" />
                    </InputAdornment>
                  ),
                }}
              />
            </Box>

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              <Typography variant="body2" sx={{ color: 'white' }}>
                Password <Box component="span" sx={{ color: '#ff6b6b' }}>*</Box>
              </Typography>
              <TextField
                fullWidth
                name="password"
                type={showPassword ? 'text' : 'password'}
                placeholder="********"
                value={formik.values.password}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={showError('password')}
                helperText={errorText('password')}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <LockOutlinedIcon fontSize="small" />
                    </InputAdornment>
                  ),
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton
                        onClick={() => setShowPassword((prev) => !prev)}
                        edge="end"
                        sx={{ color: 'text.secondary' }}
                      >
                        {showPassword ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
              {formik.values.password ? (
                <PasswordStrengthBar password={formik.values.password} />
              ) : null}
            </Box>

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              <Typography variant="body2" sx={{ color: 'white' }}>
                Confirm Password <Box component="span" sx={{ color: '#ff6b6b' }}>*</Box>
              </Typography>
              <TextField
                fullWidth
                name="confirmPassword"
                type={showConfirmPassword ? 'text' : 'password'}
                placeholder="********"
                value={formik.values.confirmPassword}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={showError('confirmPassword')}
                helperText={errorText('confirmPassword')}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <LockOutlinedIcon fontSize="small" />
                    </InputAdornment>
                  ),
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton
                        onClick={() => setShowConfirmPassword((prev) => !prev)}
                        edge="end"
                        sx={{ color: 'text.secondary' }}
                      >
                        {showConfirmPassword ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
            </Box>

            <Button
              variant="contained"
              type="submit"
              fullWidth
              disabled={checkingEmail}
            >
              {checkingEmail ? 'Checking…' : 'Create Account'}
            </Button>

          
          </Box>
        </form>
      </BaseCard>
    </Box>
  );
};

export default Signup;
